# Independent check: shortest paths, admissibility, consistency, and both searches
import heapq
edges = {('S','A'):1, ('S','B'):3, ('A','B'):3, ('A','G'):9, ('B','C'):2, ('C','G'):4}
adj = {}
for (u, v), c in edges.items():
    adj.setdefault(u, {})[v] = c; adj.setdefault(v, {})[u] = c
h = {'S':8, 'A':8, 'B':5, 'C':7, 'G':0}

def dist(src):
    d = {src: 0}; pq = [(0, src)]
    while pq:
        du, u = heapq.heappop(pq)
        if du > d[u]: continue
        for v, c in adj[u].items():
            if du + c < d.get(v, 1e9): d[v] = du + c; heapq.heappush(pq, (d[v], v))
    return d

hs = dist('G')
print(hs, 'admissible:', all(h[n] <= hs[n] for n in h),
      'consistent:', all(h[u] <= c + h[v] for u in adj for v, c in adj[u].items()))

def search(use_g):
    # graph search: goal test on selection, ties broken alphabetically by node name
    fr = [(h['S'], 'S', 0, 'S')]; closed = set()
    while fr:
        _, u, g, path = heapq.heappop(fr)
        if u in closed: continue
        if u == 'G': return g, path
        closed.add(u)
        for v, c in sorted(adj[u].items()):
            if v not in closed:
                heapq.heappush(fr, ((g + c if use_g else 0) + h[v], v, g + c, path + v))

print('A*', search(True), 'greedy', search(False))  # A* (10, 'SAG'); greedy (9, 'SBCG'); optimum is 9 via SBCG
